<template>
  <section class="app-page max-w-6xl">
    <header class="app-page-header"><div><p class="text-xs font-bold uppercase tracking-wider text-primary">Pédagogie</p><h1 class="app-page-title mt-2">Modération des cours</h1><p class="app-page-copy">Examinez les cours soumis avant leur publication.</p></div></header>
    <div class="app-panel space-y-5">
      <div class="flex flex-wrap items-end justify-between gap-4"><div><h2 class="text-lg font-bold text-ink">Cours à examiner</h2><p class="text-sm text-quiet">Les cours sont soumis à revue lorsque la modération est activée.</p></div><label class="text-sm font-semibold text-ink">Statut<select v-model="status" class="app-input mt-1"><option value="submitted">Soumis</option><option value="in_review">En cours d'examen</option><option value="published">Publiés</option><option value="suspended">Suspendus</option><option value="rejected">Rejetés</option></select></label></div>
      <div v-if="courses.isPending.value" class="space-y-3"><div v-for="n in 3" :key="n" class="app-skeleton h-24" /></div>
      <div v-else-if="courses.isError.value" class="rounded-xl bg-red-50 p-4 text-sm text-red-800" role="alert">{{ errorMessage(courses.error.value) }} <button class="underline" @click="courses.refetch()">Réessayer</button></div>
      <p v-else-if="!courses.data.value?.items.length" class="rounded-xl bg-canvas p-8 text-center text-sm text-quiet">Aucun cours pour ce statut.</p>
      <div v-else class="space-y-3"><article v-for="course in courses.data.value?.items" :key="course.key" class="rounded-xl border border-line p-5"><div class="flex flex-wrap items-start justify-between gap-3"><div><p class="text-xs font-semibold text-primary">{{ course.pathway?.name ?? 'Filière' }}</p><h3 class="mt-1 font-bold text-ink">{{ course.title }}</h3><p class="mt-1 text-xs text-quiet">Formateur : {{ course.owner?.name ?? 'Non précisé' }}</p></div><button class="app-action-secondary" @click="select(course)">{{ selected?.key === course.key ? 'Fermer' : 'Examiner' }}</button></div>
        <div v-if="selected?.key === course.key" class="mt-5 space-y-4 border-t border-line pt-5"><p class="whitespace-pre-wrap text-sm leading-6 text-quiet">{{ course.description || course.summary || 'Aucune description disponible.' }}</p><div class="rounded-xl bg-canvas p-4"><h4 class="font-bold text-ink">Contenu du cours</h4><p v-if="modules.isPending.value" class="mt-2 text-sm text-quiet">Chargement...</p><p v-else-if="modules.isError.value" class="mt-2 text-sm text-red-700">{{ errorMessage(modules.error.value) }}</p><p v-else-if="!modules.data.value?.length" class="mt-2 text-sm text-quiet">Aucun module disponible.</p><ol v-else class="mt-3 space-y-4"><li v-for="module in modules.data.value" :key="module.key" class="text-sm"><p class="font-semibold text-ink">{{ module.title }}</p><p v-if="module.summary" class="mt-1 whitespace-pre-wrap text-quiet">{{ module.summary }}</p><div v-for="chapter in module.chapters ?? []" :key="chapter.key" class="mt-3 rounded-lg border border-line bg-white p-3"><h5 class="font-semibold text-ink">{{ chapter.title }}</h5><p v-if="chapter.body" class="mt-2 whitespace-pre-wrap break-words text-quiet">{{ chapter.body }}</p><ul v-if="chapter.resources?.length" class="mt-2 space-y-2"><li v-for="resource in chapter.resources" :key="resource.key" class="border-t border-line pt-2 text-quiet"><span class="font-semibold text-ink">{{ resource.title }}</span><p v-if="resource.body" class="whitespace-pre-wrap break-words">{{ resource.body }}</p><p v-if="resource.external_url" class="break-all">{{ resource.external_url }}</p></li></ul></div></li></ol></div>
          <form v-if="['submitted', 'in_review'].includes(course.status)" class="space-y-3" @submit.prevent="submit(course)"><label class="block text-sm font-semibold text-ink">Décision<select v-model="action" class="app-input mt-1"><option value="approve">Approuver et publier</option><option value="reject">Rejeter</option></select></label><label class="block text-sm font-semibold text-ink">Motif <span class="font-normal text-quiet">{{ action === 'reject' ? '(obligatoire)' : '(facultatif)' }}</span><textarea v-model.trim="note" class="app-input mt-1" rows="3" maxlength="2000" :required="action === 'reject'" /></label><p v-if="actionError" role="alert" class="text-sm text-red-700">{{ actionError }}</p><button class="app-action-primary" :disabled="mutation.isPending.value || modules.isError.value || modules.isPending.value">{{ mutation.isPending.value ? 'Enregistrement...' : action === 'approve' ? 'Approuver et publier' : 'Rejeter le cours' }}</button></form>
        </div>
      </article></div>
      <nav v-if="courses.data.value?.pagination && (courses.data.value.pagination.last_page ?? 1) > 1" class="flex items-center justify-end gap-3" aria-label="Pagination"><button class="app-action-secondary" :disabled="page <= 1" @click="page--">Précédent</button><span class="text-sm text-quiet">{{ page }} / {{ courses.data.value.pagination.last_page }}</span><button class="app-action-secondary" :disabled="page >= (courses.data.value.pagination.last_page ?? 1)" @click="page++">Suivant</button></nav>
    </div>
  </section>
</template>
<script setup lang="ts">
import { computed, ref, watch } from 'vue'
import { useMutation, useQuery, useQueryClient } from '@tanstack/vue-query'
import { apiMeta, ApiError, http } from '@/api/http'
interface Course { key: string; title: string; status: string; description: string | null; summary: string | null; owner?: { name: string }; pathway?: { name: string } }
interface Module { key: string; title: string; summary: string | null; chapters?: Array<{ key: string; title: string; body: string | null; resources?: Array<{ key: string; title: string; body: string | null; external_url: string | null }> }> }
const status = ref('submitted'), page = ref(1), selected = ref<Course | null>(null), action = ref<'approve' | 'reject'>('approve'), note = ref(''), actionError = ref('')
const client = useQueryClient()
watch(status, () => { page.value = 1; selected.value = null })
const courses = useQuery({ queryKey: computed(() => ['moderation-courses', status.value, page.value]), queryFn: async () => { const response = await http.get<Course[]>('/admin/courses', { params: { status: status.value, page: page.value } }); return { items: response.data, pagination: apiMeta(response)?.pagination ?? null } } })
const modules = useQuery({ queryKey: computed(() => ['moderation-course-modules', selected.value?.key]), enabled: computed(() => !!selected.value), queryFn: async () => (await http.get<Module[]>(`/admin/courses/${selected.value?.key}/modules`)).data })
const mutation = useMutation({ mutationFn: (course: Course) => http.post(`/admin/courses/${course.key}/${action.value}`, { note: note.value || null }), onSuccess: () => { selected.value = null; note.value = ''; action.value = 'approve'; void client.invalidateQueries({ queryKey: ['moderation-courses'] }) } })
function select(course: Course) { selected.value = selected.value?.key === course.key ? null : course; actionError.value = ''; note.value = '' }
function submit(course: Course) { actionError.value = ''; mutation.mutate(course, { onError: (error) => { actionError.value = errorMessage(error) } }) }
function errorMessage(error: unknown) { return error instanceof ApiError ? error.displayMessage : 'Impossible de charger les informations.' }
</script>
